package com.yonlab.vision;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Only known RGB LED values are writable. Trigger state is read and never modified. */
final class BoardLed {
 static final String[] PATHS={"/sys/class/leds/wifi_red/blink","/sys/class/leds/wifi_green/blink","/sys/class/leds/wifi_blue/blink"};
 static final String[] BRIGHTNESS={"/sys/class/leds/wifi_red/brightness","/sys/class/leds/wifi_green/brightness","/sys/class/leds/wifi_blue/brightness"};
 static final String[] MAX={"/sys/class/leds/wifi_red/max_brightness","/sys/class/leds/wifi_green/max_brightness","/sys/class/leds/wifi_blue/max_brightness"};
 static final String[] TRIGGER={"/sys/class/leds/wifi_red/trigger","/sys/class/leds/wifi_green/trigger","/sys/class/leds/wifi_blue/trigger"};
 interface NodeIo {String read(String path)throws IOException;void write(String path,String value)throws IOException;}
 static final class Report {
  final String status,error,backend,fallbackReason;final Map<String,String> original,current,restored;final int dirtyCount;
  Report(String s,String e,Map<String,String> o,Map<String,String> c,Map<String,String> r,int dirty){this(s,e,o,c,r,dirty,"none","");}
  Report(String s,String e,Map<String,String> o,Map<String,String> c,Map<String,String> r,int dirty,String b,String fallback){status=s;error=e;original=new LinkedHashMap<>(o);current=new LinkedHashMap<>(c);restored=new LinkedHashMap<>(r);dirtyCount=dirty;backend=b;fallbackReason=fallback;}
 }
 private final NodeIo io;private final Map<String,String> original=new LinkedHashMap<>(),current=new LinkedHashMap<>(),restored=new LinkedHashMap<>(),maximum=new LinkedHashMap<>();private final Set<String> dirty=new LinkedHashSet<>();private String[] selected=PATHS;private String backend="none",fallbackReason="";
 BoardLed(){this(new FileNodes());}BoardLed(NodeIo io){this.io=io;}
 synchronized Report set(boolean on){String error="";try{if(dirty.isEmpty())snapshot();for(String path:selected){guard(path);dirty.add(path);String requested=on?("brightness".equals(backend)?maximum.get(path):"1"):"0";io.write(path,requested);String readback=value(path,io.read(path));current.put(path,readback);guard(path);if(!requested.equals(readback))throw new IOException("LED readback mismatch");}return report("APPLIED","");}catch(Exception e){error=e.getClass().getSimpleName()+": "+e.getMessage();}Report r=restore();return report("FAILED",error+(r.dirtyCount>0?"; restore pending":""));}
 private void snapshot()throws IOException{Map<String,String> values=new LinkedHashMap<>();maximum.clear();fallbackReason="";try{for(String path:PATHS)values.put(path,binary(io.read(path)));selected=PATHS;backend="blink";}catch(Exception e){fallbackReason=e.getClass().getSimpleName()+": "+e.getMessage();values.clear();for(int i=0;i<BRIGHTNESS.length;i++){requireNone(io.read(TRIGGER[i]));int max=number(io.read(MAX[i]));if(max<1||max>255)throw new IOException("LED max brightness unsupported");int prior=number(io.read(BRIGHTNESS[i]));if(prior>max)throw new IOException("LED original brightness unsupported");values.put(BRIGHTNESS[i],Integer.toString(prior));maximum.put(BRIGHTNESS[i],Integer.toString(max));}selected=BRIGHTNESS;backend="brightness";}original.clear();original.putAll(values);current.clear();current.putAll(values);restored.clear();}
 synchronized Report restore(){if(dirty.isEmpty())return report("NO_CHANGES","");StringBuilder error=new StringBuilder();for(String path:new ArrayList<>(dirty))try{guard(path);String prior=original.get(path);if(prior==null)throw new IOException("LED original state unavailable");io.write(path,prior);String readback=value(path,io.read(path));restored.put(path,readback);current.put(path,readback);guard(path);if(!prior.equals(readback))throw new IOException("LED restore readback mismatch");dirty.remove(path);}catch(Exception e){if(error.length()>0)error.append("; ");error.append(e.getClass().getSimpleName()).append(": ").append(e.getMessage());}return report(dirty.isEmpty()?"RESTORED":"RESTORE_FAILED",error.toString());}
 private void guard(String path)throws IOException{if("brightness".equals(backend)){int index=Arrays.asList(BRIGHTNESS).indexOf(path);if(index<0)throw new IOException("LED path");requireNone(io.read(TRIGGER[index]));}else if(!Arrays.asList(PATHS).contains(path))throw new IOException("LED path");}
 private String value(String path,String input)throws IOException{if("brightness".equals(backend)){int n=number(input),max=number(maximum.get(path));if(n>max)throw new IOException("LED readback unsupported");return Integer.toString(n);}return binary(input);}
 private Report report(String status,String error){return new Report(status,error,original,current,restored,dirty.size(),backend,fallbackReason);}
 private static String binary(String input)throws IOException{String v=input==null?"":input.trim();if(!"0".equals(v)&&!"1".equals(v))throw new IOException("LED binary value unsupported");return v;}
 private static int number(String input)throws IOException{String v=input==null?"":input.trim();if(!v.matches("[0-9]{1,3}"))throw new IOException("LED brightness value unsupported");return Integer.parseInt(v);}
 private static void requireNone(String input)throws IOException{String v=input==null?"":input;int first=v.indexOf('['),last=v.indexOf(']');if(first<0||last<first||!"none".equals(v.substring(first+1,last))||v.indexOf('[',first+1)>=0||v.indexOf(']',last+1)>=0)throw new IOException("LED trigger is not none");}
 private static final class FileNodes implements NodeIo {
  public String read(String path)throws IOException{boolean trigger=Arrays.asList(TRIGGER).contains(path);if(!trigger&&!Arrays.asList(PATHS).contains(path)&&!Arrays.asList(BRIGHTNESS).contains(path)&&!Arrays.asList(MAX).contains(path))throw new IOException("LED read path");try(FileInputStream in=new FileInputStream(path);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[128];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>(trigger?4096:64))throw new IOException("LED readback too long");out.write(bytes,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
  public void write(String path,String value)throws IOException{if(!Arrays.asList(PATHS).contains(path)&&!Arrays.asList(BRIGHTNESS).contains(path))throw new IOException("LED write path");try(FileOutputStream out=new FileOutputStream(path)){out.write(value.getBytes(StandardCharsets.UTF_8));out.flush();}}
 }
}
